# Extract the Table and Policy name
matches = re.findall(r'Table `public\.([^`]+)` has an RLS policy `([^`]+)`', linter_text)

alter_statements = ["-- Hard drop and recreate all problematic policies exactly as named in the linter"]

for table, policy in matches:
    alter_statements.append(f'DROP POLICY IF EXISTS "{policy}" ON public."{table}";')
    
    # We should also recreate a secure policy for these tables just so they still function,
    # but the secure one shouldn't clash with the old name if the old name was bad, OR we can just use the same name.
    # The linter complains about the contents, not the name.
    # We will use the same name but with secure rules.
    alter_statements.append(f'CREATE POLICY "{policy}" ON public."{table}" FOR ALL USING (auth.uid() IS NOT NULL) WITH CHECK (auth.uid() IS NOT NULL);')

with open('supabase_exact_policy_fix.sql', 'w', encoding='utf-8') as f:
    f.write('\n'.join(alter_statements))

print(f"Generated {len(matches)} policy drop/creates.")
